<?php
namespace Tests\Feature;
use Symfony\Component\Process\Process;
use Tests\TestCase;
class Milestone3gyProfileUpdateRequestScopeGateTest extends TestCase
{
 private const BASE='346a3750f1996b92c50f7bf5d72d4bc570811452';private const SUBJECT='Add profile update request scope gate';private const FILES=['backend/docs/milestone_3gy_profile_update_request_scope_gate.md','backend/tests/Feature/Milestone3gyProfileUpdateRequestScopeGateTest.php'];
 public function test_scope_finalizes_safe_first_release():void{$d=file_get_contents(__DIR__.'/../../docs/milestone_3gy_profile_update_request_scope_gate.md');foreach([self::BASE,'scope-only','`full_name`','`birth_date`','`phone`','`address_line_1`','`blood_donor_consent`','`member_code`','Both Member contact `email` and authentication email are deferred','one Pending request','`pending`, `approved`, `rejected`, and `withdrawn`','President/Admin','Secretary','Treasurer | Yes | Yes | No | No','Normal Member | Yes | Yes | No | No','409 conflict','No silent overwrite','required reason','No DELETE route','No direct member self-update','GO - 3GZ'] as $x)$this->assertStringContainsStringIgnoringCase($x,$d);}
 public function test_scope_matches_repository_member_and_disconnected_ui():void{$root=dirname(__DIR__,3);$member=file_get_contents($root.'/backend/app/Models/Member.php');$ui=file_get_contents($root.'/app/page.tsx');foreach(['full_name','birth_date','occupation','spouse_name','phone','address_line_1','blood_group','blood_donor_consent'] as $x)$this->assertStringContainsString("'{$x}'",$member);$this->assertStringContainsString('The profile update approval workflow is not connected yet.',$ui);$this->assertStringContainsString('Prototype approval simulation',$ui);}
 public function test_changed_file_scope_is_lifecycle_safe():void{$root=dirname(__DIR__,3);$c=$this->find($root);if(!$c){$this->assertSame(self::BASE,trim($this->git($root,['rev-parse','HEAD'])));$lines=array_values(array_filter(explode("\n",rtrim($this->git($root,['status','--porcelain=v1','-uall']),"\r\n"))));$files=array_map(fn($x)=>str_replace('\\','/',substr($x,3)),$lines);}else{$files=$this->lines($root,['diff-tree','--no-commit-id','--name-only','-r',$c]);}$expected=self::FILES;sort($files);sort($expected);$this->assertSame($expected,$files);}
 private function find($r):?string{$m=[];foreach($this->lines($r,['log','--all','--format=%H%x09%s']) as $l){[$h,$s]=array_pad(explode("\t",$l,2),2,'');if($s===self::SUBJECT)$m[]=$h;}$this->assertLessThanOrEqual(1,count($m));return $m[0]??null;}private function lines($r,$a):array{return array_values(array_filter(explode("\n",trim($this->git($r,$a)))));}private function git($r,$a):string{$p=new Process(['git',...$a],$r);$p->setTimeout(30);$p->run();$this->assertTrue($p->isSuccessful(),$p->getErrorOutput());return str_replace("\r\n","\n",$p->getOutput());}
}
